const responseJson = async (response) => {
  const text = await response.text();
  let body = null;
  if (text) {
    try {
      body = JSON.parse(text);
    } catch {
      body = text;
    }
  }
  if (!response.ok) {
    throw new Error(\`HTTP \${response.status} \${response.statusText}: \${typeof body === "string" ? body : JSON.stringify(body)}\`);
  }
  return body;
};

